BEGIN;
DO $test$
DECLARE h uuid; dad uuid; mom uuid; child1 uuid; child2 uuid; outsider uuid; private_id uuid:=gen_random_uuid();parents_id uuid:=gen_random_uuid();family_id uuid:=gen_random_uuid();kid_id uuid:=gen_random_uuid();r jsonb;n integer;
BEGIN
 SELECT household_id INTO STRICT h FROM bb_planner_private.routines WHERE routine_key='prepare_for_tomorrow_v1';
 SELECT user_id INTO dad FROM public.bb_planner_members WHERE household_id=h AND member_role='adult' ORDER BY user_id LIMIT 1;
 SELECT user_id INTO mom FROM public.bb_planner_members WHERE household_id=h AND member_role='adult' AND user_id<>dad LIMIT 1;
 SELECT user_id INTO child1 FROM public.bb_planner_members WHERE household_id=h AND member_role='child' ORDER BY user_id LIMIT 1;
 SELECT user_id INTO child2 FROM public.bb_planner_members WHERE household_id=h AND member_role='child' AND user_id<>child1 LIMIT 1;
 SELECT user_id INTO outsider FROM public.bb_planner_members m WHERE NOT EXISTS(SELECT FROM public.bb_planner_members x WHERE x.household_id=h AND x.user_id=m.user_id) LIMIT 1;
 IF mom IS NULL OR child2 IS NULL OR outsider IS NULL THEN RAISE EXCEPTION 'Missing fixture members';END IF;
 PERFORM set_config('request.jwt.claim.sub',dad::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM public.bb_calendar_save(h,private_id,NULL,'Private rollback fixture','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'private','Private note');
 PERFORM public.bb_calendar_save(h,parents_id,NULL,'Parents rollback fixture','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'parents','Parent note');
 PERFORM public.bb_calendar_save(h,family_id,NULL,'Family rollback fixture','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','Family note');
 PERFORM public.bb_calendar_save(h,family_id,NULL,'Family rollback fixture','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','Family note');
 SELECT count(*) INTO n FROM public.bb_calendar_events WHERE id IN(private_id,parents_id,family_id);IF n<>3 THEN RAISE EXCEPTION 'Owner visibility/retry';END IF;
 BEGIN PERFORM public.bb_calendar_save(h,gen_random_uuid(),NULL,'Invalid interval','2027-03-12 23:00+00','2027-03-12 22:00+00',false,'family','');RAISE EXCEPTION 'Invalid interval accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',mom::text,true);
 SELECT count(*) INTO n FROM public.bb_calendar_events WHERE id IN(private_id,parents_id,family_id);IF n<>2 THEN RAISE EXCEPTION 'Parent private leak';END IF;
 BEGIN PERFORM public.bb_calendar_cancel(private_id,1);RAISE EXCEPTION 'Parent private mutation allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_calendar_save(h,family_id,1,'Visibility attempt','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'parents','');RAISE EXCEPTION 'Noncreator visibility allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',child1::text,true);
 SELECT count(*) INTO n FROM public.bb_calendar_events WHERE id IN(private_id,parents_id,family_id);IF n<>1 THEN RAISE EXCEPTION 'Child parent/private leak';END IF;
 PERFORM public.bb_calendar_save(h,kid_id,NULL,'Child-created rollback event','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','');
 BEGIN PERFORM public.bb_calendar_save(h,gen_random_uuid(),NULL,'No parents scope','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'parents','');RAISE EXCEPTION 'Child parents creation allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_calendar_save(h,family_id,1,'Sibling edit attempt','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','');RAISE EXCEPTION 'Child other-event edit allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.bb_calendar_save(h,kid_id,1,'Child revised rollback event','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','');IF (r->>'version')::integer<>2 OR r->>'created_by'<>child1::text THEN RAISE EXCEPTION 'Child edit/creator';END IF;
 BEGIN PERFORM public.bb_calendar_cancel(kid_id,1);RAISE EXCEPTION 'Stale cancel allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',child2::text,true);SELECT count(*) INTO n FROM public.bb_calendar_events WHERE id=kid_id;IF n<>1 THEN RAISE EXCEPTION 'Sibling cannot see family event';END IF;
 BEGIN PERFORM public.bb_calendar_cancel(kid_id,2);RAISE EXCEPTION 'Sibling cancel allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',mom::text,true);r:=public.bb_calendar_cancel(kid_id,2);IF r->>'status'<>'cancelled' THEN RAISE EXCEPTION 'Parent management';END IF;
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);SELECT count(*) INTO n FROM public.bb_calendar_events WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Foreign household leak';END IF;
 BEGIN PERFORM public.bb_calendar_save(h,gen_random_uuid(),NULL,'Foreign attempt','2027-03-12 22:00+00','2027-03-12 23:00+00',false,'family','');RAISE EXCEPTION 'Foreign write allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'SET LOCAL ROLE postgres';
 IF has_function_privilege('anon','public.bb_calendar_cancel(uuid,bigint)','EXECUTE') OR has_table_privilege('authenticated','public.bb_calendar_events','INSERT') OR has_table_privilege('authenticated','bb_planner_private.calendar_changes','SELECT') THEN RAISE EXCEPTION 'ACL exposure';END IF;
 SELECT count(*) INTO n FROM bb_planner_private.calendar_changes WHERE event_id=kid_id;IF n<>3 THEN RAISE EXCEPTION 'Audit history count';END IF;
 RAISE NOTICE 'PASS visibility, child create/own edit, sibling denial, parent management, stale guards, idempotent creation, history, private ACLs, foreign denial';
END $test$;
ROLLBACK;
